final class TfaSplitsTrackerPanel extends PluginPanel
{
	private static final Color BACKGROUND = new Color(30, 30, 30);
	private static final Color CARD = new Color(39, 39, 39);
	private static final Color BORDER = new Color(57, 57, 57);
	private static final Color TEXT = new Color(225, 225, 225);
	private static final Color MUTED = new Color(165, 165, 165);
	private static final Color GREEN = new Color(139, 190, 153);
	private static final Color RED = new Color(213, 145, 140);
	private static final Color GOLD = new Color(207, 184, 129);
	private static final Color BLUE = new Color(151, 178, 207);
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("MMM d, HH:mm").withZone(ZoneId.systemDefault());
	private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("EEE, MMM d, yyyy", Locale.ENGLISH);
	private final JPanel live = column();
	private final JPanel history = column();
	private final JLabel count = label("0", 13, TEXT);
	private final JLabel best = label("--:--", 13, TEXT);
	private final JLabel total = label("--:--", 26, TEXT);
	private final JLabel roomClock = label("", 11, MUTED);
	private final JLabel notice = label("", 11, TEXT);
	private final JComboBox<String> sizes = new JComboBox<>(new String[]{"All team sizes", "Solo", "2 players", "3 players", "4 players", "5 players", "6 players", "7 players", "8 players"});
	private final JTextField search = new JTextField();
	private final JCheckBox hideUnfinished = new JCheckBox("Hide Failed/Abandoned Raids");
	private final Set<String> expanded = new HashSet<>();
	private final Set<LocalDate> collapsedDays = new HashSet<>();
	private TfaTracker data = new TfaTracker();
	private TfaLiveState liveState = TfaLiveState.UNAVAILABLE;
	private final BiConsumer<String, String> delete;
	private final JButton undo = new JButton("Undo last deletion");
	private final JButton compare = new JButton("Compare Raids");
	private JDialog comparisonWindow;
	private TfaRaidComparisonPanel comparisonPanel;

	TfaSplitsTrackerPanel()
	{
		this((id, room) ->
		{
		}, () ->
		{
		});
	}

	TfaSplitsTrackerPanel(BiConsumer<String, String> delete, Runnable undoDelete)
	{
		this.delete = delete;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(BACKGROUND);
		setBorder(BorderFactory.createEmptyBorder(12, 8, 12, 8));
		JPanel header = column();
		header.add(label("TFA Splits Tracker", 17, TEXT));
		header.add(Box.createVerticalStrut(3));
		header.add(label("The Fractured Archive", 11, MUTED));
		header.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, BORDER), BorderFactory.createEmptyBorder(0, 0, 10, 0)));
		count.setForeground(GREEN);
		best.setForeground(GOLD);
		total.setForeground(BLUE);
		add(header);
		add(Box.createVerticalStrut(12));
		JPanel stats = column();
		stats.add(stat("Completed raids", count));
		stats.add(Box.createVerticalStrut(6));
		stats.add(stat("Best raid", best));
		add(stats);
		add(Box.createVerticalStrut(12));
		add(live);
		add(Box.createVerticalStrut(14));
		add(label("Raid history", 12, TEXT));
		compare.setAlignmentX(LEFT_ALIGNMENT);
		compare.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
		compare.setBackground(CARD);
		compare.setForeground(TEXT);
		compare.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
		compare.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(BORDER),
			BorderFactory.createEmptyBorder(6, 8, 6, 8)));
		compare.setFocusPainted(false);
		compare.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		compare.addActionListener(e -> openComparison());
		add(Box.createVerticalStrut(7));
		add(compare);
		undo.setForeground(MUTED);
		undo.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
		undo.setAlignmentX(LEFT_ALIGNMENT);
		undo.setContentAreaFilled(false);
		undo.setBorder(BorderFactory.createEmptyBorder(5, 0, 5, 0));
		undo.addActionListener(e -> undoDelete.run());
		add(undo);
		add(Box.createVerticalStrut(7));
		sizes.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
		sizes.setAlignmentX(LEFT_ALIGNMENT);
		sizes.setBackground(CARD);
		sizes.setForeground(TEXT);
		sizes.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		sizes.addActionListener(e -> rebuildHistory());
		add(sizes);
		add(Box.createVerticalStrut(7));
		hideUnfinished.setAlignmentX(LEFT_ALIGNMENT);
		hideUnfinished.setOpaque(false);
		hideUnfinished.setForeground(TEXT);
		hideUnfinished.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
		hideUnfinished.setToolTipText("Show only completed raids; also hides left and interrupted attempts. Saved raids are kept.");
		hideUnfinished.addActionListener(e -> rebuildHistory());
		add(hideUnfinished);
		add(Box.createVerticalStrut(7));
		add(label("Search player, status or time", 10, MUTED));
		add(Box.createVerticalStrut(4));
		search.setToolTipText("Filter by party member or raid status. " + TfaRaidSearch.TIME_HELP);
		search.setAlignmentX(LEFT_ALIGNMENT);
		search.setBackground(CARD);
		search.setForeground(TEXT);
		search.setCaretColor(TEXT);
		search.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
		search.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(BORDER),
			BorderFactory.createEmptyBorder(4, 7, 4, 7)));
		search.putClientProperty("JTextField.placeholderText", "Player, status or 12:34...");
		search.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		search.setPreferredSize(new Dimension(190, 28));
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			public void insertUpdate(DocumentEvent e)
			{
				rebuildHistory();
			}

			public void removeUpdate(DocumentEvent e)
			{
				rebuildHistory();
			}

			public void changedUpdate(DocumentEvent e)
			{
				rebuildHistory();
			}
		});
		add(search);
		add(Box.createVerticalStrut(8));
		add(history);
		add(notice);
		update(data, true, false);
	}

	void stop()
	{
		Runnable close = () ->
		{
			if (comparisonWindow != null)
			{
				comparisonWindow.dispose();
				comparisonWindow = null;
				comparisonPanel = null;
			}
		};
		if (SwingUtilities.isEventDispatchThread())
		{
			close.run();
		}
		else
		{
			SwingUtilities.invokeLater(close);
		}
	}

	void update(TfaTracker snapshot, boolean storageHealthy, boolean available)
	{
		update(snapshot, storageHealthy, new TfaLiveState(available, "", -1));
	}

	void update(TfaTracker snapshot, boolean storageHealthy, TfaLiveState state)
	{
		data = snapshot;
		liveState = state;
		undo.setVisible(data.deleted != null);
		compare.setEnabled(data.raids.stream().anyMatch(r -> !r.active()));
		if (comparisonWindow != null && comparisonWindow.isDisplayable())
		{
			comparisonPanel.setRaids(data.raids);
		}
		notice.setText(storageHealthy ? "" : "History could not be loaded/saved.");
		long completed = data.raids.stream().filter(r -> "Completed".equals(r.status)).count();
		count.setText(Long.toString(completed));
		long pb = data.raids.stream().filter(r -> "Completed".equals(r.status) && r.completeSplits())
			.mapToLong(r -> r.total).filter(t -> t >= 0).min().orElse(-1);
		best.setText(TfaRaid.time(pb));
		best.setToolTipText("Best total among fully recorded raids; history can be filtered by team size below");
		rebuildLive();
		rebuildHistory();
	}

	void updateLiveState(TfaLiveState state)
	{
		boolean rebuild = liveState.inRaid != state.inRaid || !liveState.status.equals(state.status);
		liveState = state;
		if (rebuild) { rebuildLive(); }
		else { updateClock(); }
	}

	private void openComparison()
	{
		if (comparisonWindow == null || !comparisonWindow.isDisplayable())
		{
			comparisonPanel = new TfaRaidComparisonPanel(data.raids);
			comparisonWindow = new JDialog(SwingUtilities.getWindowAncestor(this), "TFA Splits Tracker — Compare Raids", Dialog.ModalityType.MODELESS);
			comparisonWindow.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);
			comparisonWindow.setContentPane(comparisonPanel);
			comparisonWindow.setMinimumSize(new Dimension(900, 450));
			comparisonWindow.setSize(1200, 760);
			comparisonWindow.setLocationRelativeTo(SwingUtilities.getWindowAncestor(this));
		}
		comparisonWindow.setVisible(true);
		comparisonWindow.toFront();
	}

	private void rebuildLive()
	{
		live.removeAll();
		JPanel card = card();
		TfaRaid raid = liveState.inRaid ? data.current() : null;
		accent(card, raid == null ? BORDER : BLUE);
		card.add(label(raid == null ? "RAID STATUS" : "LIVE RAID", 10, raid == null ? MUTED : BLUE));
		card.add(Box.createVerticalStrut(6));
		if (raid == null)
		{
			card.add(label(liveState.status.isEmpty() ? "Waiting for challenge start" : liveState.status, 12, TEXT));
			card.add(Box.createVerticalStrut(5));
			card.add(label(data.raids.isEmpty() || data.raids.get(0).active() ? "Raids are recorded automatically."
				: "Last raid: " + data.raids.get(0).status, 10, MUTED));
		}
		else
		{
			card.add(total);
			card.add(roomClock);
			card.add(Box.createVerticalStrut(7));
			int completedRooms = (int) raid.splits.stream().filter(s -> s.duration >= 0).count();
			JProgressBar progress = new JProgressBar(0, 5);
			progress.setValue(completedRooms);
			progress.setForeground(GREEN);
			progress.setBackground(BORDER);
			progress.setBorderPainted(false);
			progress.setAlignmentX(LEFT_ALIGNMENT);
			progress.setMaximumSize(new Dimension(Integer.MAX_VALUE, 4));
			progress.setToolTipText(completedRooms + " of 5 rooms recorded");
			card.add(progress);
			card.add(Box.createVerticalStrut(7));
			card.add(label(TfaPersonalBest.status(raid), 10, raid.personalBest == null ? MUTED : GOLD));
			card.add(Box.createVerticalStrut(10));
			addSplits(card, raid);
			addParty(card, raid);
			JPopupMenu menu = new JPopupMenu();
			JMenuItem reset = new JMenuItem("Reset current tracker");
			reset.setToolTipText("Discard this run and wait for the next Archive Guardian start");
			reset.addActionListener(e -> delete.accept(raid.id, null));
			menu.add(reset);
			attachPopup(card, menu);
		}
		live.add(card);
		updateClock();
		live.revalidate();
		live.repaint();
	}

	private void updateClock()
	{
		TfaRaid raid = data.current();
		if (raid == null)
		{
			return;
		}
		if (!liveState.inRaid)
		{
			total.setText(TfaRaid.time(raid.total));
			roomClock.setText("Waiting for raid data");
			return;
		}
		total.setText(TfaRaid.time(liveState.elapsed >= 0 ? liveState.elapsed : raid.total));
		total.setToolTipText(liveState.elapsed >= 0 ? "Current raid time from the game's HUD"
			: "Last recorded raid split; live HUD clock unavailable");
		TfaRaid.Split last = raid.splits.isEmpty() ? null : raid.splits.get(raid.splits.size() - 1);
		roomClock.setText(last != null && last.duration < 0
			? shortRoom(last.room) + "  /  In progress"
			: liveState.status.isEmpty() ? "Between rooms" : liveState.status);
	}

	private void rebuildHistory()
	{
		history.removeAll();
		String query = search.getText().trim().toLowerCase(Locale.ROOT);
		int selectedSize = sizes.getSelectedIndex();
		Map<LocalDate, List<TfaRaid>> days = data.raids.stream()
			.filter(raid -> !raid.active())
			.filter(raid -> !hideUnfinished.isSelected() || "Completed".equals(raid.status))
			.filter(raid -> selectedSize == 0 || (raid.teamSize > 0 ? raid.teamSize : raid.members.size()) == selectedSize)
			.filter(raid -> TfaRaidSearch.matches(raid, query, raid.status + " " + String.join(" ", raid.members)))
			.sorted(Comparator.comparingLong((TfaRaid raid) -> raid.started).reversed())
			.collect(Collectors.groupingBy(raid -> Instant.ofEpochMilli(raid.started).atZone(ZoneId.systemDefault()).toLocalDate(),
				() -> new TreeMap<LocalDate, List<TfaRaid>>(Comparator.reverseOrder()), Collectors.toList()));
		for (Map.Entry<LocalDate, List<TfaRaid>> entry : days.entrySet())
		{
			LocalDate day = entry.getKey();
			List<TfaRaid> raids = entry.getValue();
			boolean collapsed = collapsedDays.contains(day);
			JPanel heading = new JPanel(new BorderLayout(4, 0));
			heading.setOpaque(false);
			heading.setAlignmentX(LEFT_ALIGNMENT);
			heading.setBorder(BorderFactory.createEmptyBorder(6, 0, 7, 0));
			JButton toggle = new JButton((collapsed ? "\u25b8 " : "\u25be ") + DAY.format(day));
			toggle.setName("day-" + day);
			toggle.setHorizontalAlignment(SwingConstants.LEFT);
			toggle.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
			toggle.setForeground(TEXT);
			toggle.setBorder(BorderFactory.createEmptyBorder());
			toggle.setContentAreaFilled(false);
			toggle.setFocusPainted(false);
			toggle.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			toggle.addActionListener(e ->
			{
				if (!collapsedDays.remove(day))
				{
					collapsedDays.add(day);
				}
				rebuildHistory();
			});
			heading.add(toggle, BorderLayout.CENTER);
			heading.add(label(raids.size() + (raids.size() == 1 ? " raid" : " raids"), 11, TEXT), BorderLayout.EAST);
			long completed = raids.stream().filter(r -> "Completed".equals(r.status)).count();
			heading.setToolTipText(completed + " completed / " + (raids.size() - completed)
				+ " other attempts. Saved raids by local start date; counts reflect the current filters.");
			history.add(heading);
			if (collapsed)
			{
				continue;
			}
			for (TfaRaid raid : raids)
			{
				history.add(historyCard(raid));
				history.add(Box.createVerticalStrut(7));
			}
		}
		if (days.isEmpty())
		{
			history.add(label(data.raids.isEmpty() ? "Your raid history will appear here." : "No matching raids.", 11, MUTED));
		}
		history.revalidate();
		history.repaint();
	}

	private JPanel historyCard(TfaRaid raid)
	{
		int team = raid.teamSize > 0 ? raid.teamSize : raid.members.size();
		JPanel card = card();
		boolean open = expanded.contains(raid.id);
		JButton toggle = new JButton((open ? "\u25be " : "\u25b8 ") + DATE.format(Instant.ofEpochMilli(raid.started)));
		toggle.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
		toggle.setForeground(TEXT);
		toggle.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		toggle.setContentAreaFilled(false);
		toggle.setFocusPainted(false);
		toggle.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		toggle.setAlignmentX(LEFT_ALIGNMENT);
		toggle.addActionListener(e ->
		{
			if (!expanded.remove(raid.id))
			{
				expanded.add(raid.id);
			}
			rebuildHistory();
		});
		card.add(toggle);
		boolean completed = "Completed".equals(raid.status);
		Color statusColor = completed ? GREEN : "Failed".equals(raid.status) ? RED : MUTED;
		accent(card, statusColor);
		card.add(row(raid.status, TfaRaid.time(raid.total), statusColor, 15));
		card.add(Box.createVerticalStrut(4));
		card.add(label((team == 0 ? "Unknown team" : team + (team == 1 ? " player" : " players"))
			+ "  /  " + raid.splits.stream().filter(s -> s.duration >= 0).count() + " rooms", 10, MUTED));
		if (completed && !raid.completeSplits())
		{
			card.add(label("Partial room history", 10, MUTED));
		}
		if (open)
		{
			card.add(Box.createVerticalStrut(10));
			addSplits(card, raid);
			card.add(Box.createVerticalStrut(7));
			card.add(row("Combat", TfaRaid.time(raid.combatTime()), MUTED, 11));
			if (raid.completeSplits() && raid.total >= raid.combatTime())
			{
				card.add(row("Between rooms", TfaRaid.time(raid.total - raid.combatTime()), MUTED, 11));
			}
			addParty(card, raid);
		}
		JPopupMenu menu = new JPopupMenu();
		JMenuItem remove = new JMenuItem("Delete raid");
		remove.addActionListener(e -> delete.accept(raid.id, null));
		menu.add(remove);
		attachPopup(card, menu);
		return card;
	}

	private void addSplits(JPanel card, TfaRaid raid)
	{
		card.add(row("Room", "Time", MUTED, 10));
		for (TfaRaid.Split split : raid.splits)
		{
			card.add(Box.createVerticalStrut(7));
			JPanel line = row(shortRoom(split.room), TfaRaid.time(split.duration), split.duration < 0 ? MUTED : TEXT, 11);
			line.setToolTipText(split.room + " | Cumulative: " + TfaRaid.time(split.cumulative));
			if (!raid.active())
			{
				JPopupMenu menu = new JPopupMenu();
				JMenuItem remove = new JMenuItem("Delete room time");
				remove.addActionListener(e -> delete.accept(raid.id, split.room));
				menu.add(remove);
				JMenuItem removeRaid = new JMenuItem("Delete raid");
				removeRaid.addActionListener(e -> delete.accept(raid.id, null));
				menu.add(removeRaid);
				attachPopup(line, menu);
			}
			card.add(line);
			addPhases(card, raid, split);
			if (raid.personalBest != null && split.duration >= 0)
			{
				TfaRaid.Split reference = raid.personalBest.stage(split);
				if (reference != null && split.cumulative >= 0)
				{
					if (reference.room.equals(split.room))
					{
						long roomDelta = split.duration - reference.duration;
						card.add(row("Room vs PB", TfaPersonalBest.delta(roomDelta),
							roomDelta == 0 ? MUTED : roomDelta < 0 ? GREEN : RED, 10));
					}
					Color deltaColor = split.cumulative == reference.cumulative ? MUTED
						: split.cumulative < reference.cumulative ? GREEN : RED;
					JPanel delta = row("Raid vs PB", TfaPersonalBest.delta(split.cumulative - reference.cumulative), deltaColor, 10);
					delta.setToolTipText("Against the same stage of your PB run: " + raid.personalBest.comparison(split));
					card.add(delta);
					if (!reference.room.equals(split.room)) { card.add(label("PB stage used " + shortRoom(reference.room), 10, MUTED)); }
				}
			}
		}
	}

	private static void attachPopup(JComponent component, JPopupMenu menu)
	{
		if (component.getComponentPopupMenu() == null)
		{
			component.setComponentPopupMenu(menu);
		}
		for (Component child : component.getComponents())
		{
			if (child instanceof JComponent)
			{
				attachPopup((JComponent) child, component.getComponentPopupMenu());
			}
		}
	}

	private static void addPhases(JPanel card, TfaRaid raid, TfaRaid.Split split)
	{
		for (TfaRaid.Phase phase : split.phases)
		{
			boolean active = raid.active() && split.duration < 0 && phase == split.phases.get(split.phases.size() - 1);
			JPanel line = row(TfaOcellus.label(phase.number), phase.duration >= 0 ? TfaRaid.time(phase.duration)
				: active ? "In progress" : "Unrecorded", MUTED, 10);
			line.setBorder(BorderFactory.createEmptyBorder(3, 6, 0, 0));
			line.setToolTipText("Game-tick phase timing. Ocellus split: " + TfaRaid.time(phase.cumulative));
			card.add(line);
			TfaRaid.Phase reference = raid.personalBest == null ? null : raid.personalBest.phase(split, phase.number);
			if (reference != null && phase.duration >= 0)
			{
				long delta = phase.duration - reference.duration;
				JPanel comparison = row("Phase vs PB", TfaPersonalBest.delta(delta), delta < 0 ? GREEN : delta > 0 ? RED : MUTED, 10);
				comparison.setBorder(BorderFactory.createEmptyBorder(0, 6, 0, 0));
				card.add(comparison);
			}
		}
	}

	private static void addParty(JPanel card, TfaRaid raid)
	{
		card.add(Box.createVerticalStrut(12));
		card.add(label("Party", 10, MUTED));
		card.add(Box.createVerticalStrut(5));
		if (raid.members.isEmpty())
		{
			card.add(label("Roster not captured", 11, MUTED));
		}
		for (String member : raid.members)
		{
			JLabel name = label(member, 11, TEXT);
			name.setToolTipText(member);
			card.add(name);
		}
	}

	private static String shortRoom(String name)
	{
		return name.equals("Dreadnoth the Jellied") ? "Dreadnoth" : name;
	}

	private static JPanel stat(String title, JLabel value)
	{
		JPanel panel = new JPanel(new BorderLayout(8, 0));
		panel.setOpaque(false);
		panel.setAlignmentX(LEFT_ALIGNMENT);
		panel.add(label(title, 11, MUTED), BorderLayout.CENTER);
		panel.add(value, BorderLayout.EAST);
		return panel;
	}

	private static JPanel row(String name, String value, Color color, int size)
	{
		JPanel row = new JPanel(new BorderLayout(5, 0));
		row.setOpaque(false);
		row.setAlignmentX(LEFT_ALIGNMENT);
		row.add(label(name, Math.min(size, 12), color), BorderLayout.CENTER);
		JLabel right = label(value, size, color);
		right.setHorizontalAlignment(SwingConstants.RIGHT);
		row.add(right, BorderLayout.EAST);
		return row;
	}

	private static JLabel label(String text, int size, Color color)
	{
		JLabel label = new JLabel(text);
		// Player names are plain text, including names beginning with an HTML-like prefix.
		label.putClientProperty("html.disable", Boolean.TRUE);
		label.setFont(new Font(Font.SANS_SERIF, size >= 17 ? Font.BOLD : Font.PLAIN, size));
		label.setForeground(color);
		label.setAlignmentX(LEFT_ALIGNMENT);
		return label;
	}

	private static JPanel column()
	{
		JPanel panel = new JPanel();
		panel.setOpaque(false);
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setAlignmentX(LEFT_ALIGNMENT);
		return panel;
	}

	private static JPanel card()
	{
		JPanel panel = new JPanel();
		panel.setBackground(CARD);
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setAlignmentX(LEFT_ALIGNMENT);
		panel.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(BORDER),
			BorderFactory.createEmptyBorder(9, 9, 9, 9)));
		return panel;
	}

	private static void accent(JPanel card, Color color)
	{
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(1, 3, 1, 1, color), BorderFactory.createEmptyBorder(9, 7, 9, 9)));
	}
}

package com.tfasplitstracker;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MessageNode;
import net.runelite.api.NPC;
import net.runelite.api.WorldView;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarClientStrChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

@Slf4j
@PluginDescriptor(
	name = "TFA Splits Tracker",
	description = "Fractured Archive raid history, server room splits, total times and party members",
	tags = {"tfa", "fractured", "archive", "raid", "splits", "timer", "party"},
	enabledByDefault = true
)
public class TfaSplitsTrackerPlugin extends Plugin
{
	private static final String GROUP = TfaSplitsTrackerConfig.GROUP;
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ClientToolbar toolbar;
	@Inject private ConfigManager configManager;
	@Inject private Gson gson;
	@Inject private TfaSplitsTrackerConfig config;
	@Inject private ChatMessageManager chatMessageManager;
	@Inject private InfoBoxManager infoBoxManager;
	@Inject private OverlayManager overlayManager;
	@Inject private TfaSplitsOverlay overlay;
	private TfaOcellus ocellus = new TfaOcellus();
	private TfaTracker tracker = new TfaTracker();
	private TfaSplitsTrackerPanel panel;
	private NavigationButton navigation;
	private volatile boolean running;
	private boolean storageHealthy = true;
	private volatile boolean liveAvailable;
	private volatile TfaRaid displayRaid;
	private volatile TfaLiveState liveState = TfaLiveState.UNAVAILABLE;
	private boolean raidSessionActive;
	private boolean awaitingRaidStart;

	@Provides
	TfaSplitsTrackerConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(TfaSplitsTrackerConfig.class);
	}

	@Override
	protected void startUp()
	{
		running = true;
		overlayManager.add(overlay);
		panel = new TfaSplitsTrackerPanel(this::delete, this::undoDelete);
		navigation = NavigationButton.builder().tooltip("TFA Splits Tracker").icon(icon()).priority(7).panel(panel).build();
		toolbar.addNavigation(navigation);
		clientThread.invokeLater(() ->
		{
			if (running)
			{
				load();
				reconcile(false);
				refreshRaidState();
				publish();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		running = false;
		overlayManager.remove(overlay);
		ocellus = new TfaOcellus();
		infoBoxManager.removeIf(box -> box instanceof TfaSplitInfoBox);
		displayRaid = null;
		liveState = TfaLiveState.UNAVAILABLE;
		raidSessionActive = false;
		awaitingRaidStart = false;
		toolbar.removeNavigation(navigation);
		panel.stop();
		// Every accepted timing and roster update has already been persisted.
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		clientThread.invokeLater(() ->
		{
			if (running)
			{
				load();
				reconcile(false);
				refreshRaidState();
				publish();
			}
		});
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		onProfileChanged(new ProfileChanged());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (running && configManager.getRSProfileKey() != null && event.getType() == ChatMessageType.GAMEMESSAGE)
		{
			// Reconcile older messages first, including when a callback was not delivered.
			reconcile(true);
			boolean changed = accept(event.getMessage(), event.getTimestamp() * 1000L, true);
			TfaRaid.Split room = liveOcellus();
			if (room != null && room.started == event.getTimestamp() * 1000L
				&& "Challenge started: Ocellus.".equals(TfaLiveState.clean(event.getMessage())))
			{
				int previous = room.phases.size();
				ocellus.begin(room, client.getTickCount());
				changed |= room.phases.size() != previous;
			}
			if (changed)
			{
				captureParty();
				saveAndPublish();
			}
		}
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event) { observeOcellus(event.getNpc(), false, true); }

	@Subscribe
	public void onNpcSpawned(NpcSpawned event) { observeOcellus(event.getNpc(), false, false); }

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (event.getActor() instanceof NPC && event.getActor().getAnimation() == TfaOcellus.DESTROY_QUADRANT_ANIMATION)
		{
			observeOcellus((NPC) event.getActor(), true, true);
		}
	}

	private void observeOcellus(NPC npc, boolean quadrantDestroyed, boolean boundary)
	{
		if (!running || configManager.getRSProfileKey() == null || client.getGameState() != GameState.LOGGED_IN
			|| npc.getWorldView() != client.getTopLevelWorldView()
			|| npc.getId() != TfaOcellus.VINES_NPC && npc.getId() != TfaOcellus.PORTALS_NPC
				&& npc.getId() != TfaOcellus.QUADRANTS_NPC) { return; }
		reconcile(true);
		TfaRaid.Split room = liveOcellus();
		if (room == null) { return; }
		TfaRaid before = tracker.current().copy();
		boolean changed = quadrantDestroyed
			? npc.getId() == TfaOcellus.QUADRANTS_NPC && ocellus.destroyQuadrant(room, client.getTickCount())
			: ocellus.observe(room, npc.getId(), client.getTickCount(), boundary);
		if (changed)
		{
			announce(before);
			saveAndPublish();
		}
	}

	private TfaRaid.Split liveOcellus()
	{
		TfaRaid raid = tracker.current();
		if (raid == null || raid.splits.isEmpty()) { return null; }
		TfaRaid.Split last = raid.splits.get(raid.splits.size() - 1);
		return "Ocellus".equals(last.room) && last.duration < 0 ? last : null;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (running)
		{
			reconcile(true);
			refreshRaidState();
			if (captureParty())
			{
				saveAndPublish();
			}
			if (liveAvailable != raidHudVisible())
			{
				publish();
			}
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (!running) { return; }
		updateLiveState(readLiveState());
	}

	private void updateLiveState(TfaLiveState state)
	{
		boolean enteredRaid = state.inRaid && !raidSessionActive;
		if (enteredRaid)
		{
			raidSessionActive = true;
			awaitingRaidStart = tracker.current() == null;
		}
		WorldView world = client.getTopLevelWorldView();
		if (client.getGameState() == GameState.LOGGED_IN && client.getLocalPlayer() != null
			&& world != null && !world.isInstance())
		{
			raidSessionActive = false;
			awaitingRaidStart = false;
		}
		TfaLiveState previous = liveState;
		if (state.inRaid == previous.inRaid && state.elapsed == previous.elapsed && state.status.equals(previous.status)) { return; }
		liveState = state;
		if (enteredRaid)
		{
			// A new instance starts with no splits, before the first challenge chat arrives.
			publish();
		}
		TfaSplitsTrackerPanel target = panel;
		SwingUtilities.invokeLater(() ->
		{
			if (running && panel == target) { target.updateLiveState(state); }
		});
	}

	private TfaLiveState readLiveState()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return client.getGameState() == GameState.LOADING && raidSessionActive
				? new TfaLiveState(true, "Loading raid", -1) : TfaLiveState.UNAVAILABLE;
		}
		boolean hudVisible = raidHudVisible();
		WorldView world = client.getTopLevelWorldView();
		// The game hides the HUD between encounters; the instance/session outlives it.
		boolean inRaid = world != null && world.isInstance()
			&& (hudVisible || raidSessionActive || tracker.current() != null);
		Widget status = client.getWidget(inRaid ? InterfaceID.TfaHud.RAID_STATE : InterfaceID.TfaHud.STATUS);
		Widget clock = client.getWidget(InterfaceID.TfaHud.RAID_TIMER);
		String text = !hudVisible || status == null || status.isHidden() ? "" : TfaLiveState.clean(status.getText());
		if (inRaid && !hudVisible)
		{
			TfaRaid raid = tracker.current();
			TfaRaid.Split last = raid == null || raid.splits.isEmpty() ? null : raid.splits.get(raid.splits.size() - 1);
			text = last != null && last.duration >= 0 ? "Between rooms" : "Raid HUD unavailable";
		}
		return new TfaLiveState(inRaid, text,
			!inRaid || !hudVisible || clock == null || clock.isHidden() ? -1 : TfaLiveState.parseClock(clock.getText()));
	}

	private void refreshRaidState()
	{
		updateLiveState(readLiveState());
		// Loading, reconnecting and temporary HUD loss are not evidence of leaving.
		WorldView world = client.getTopLevelWorldView();
		if (client.getGameState() == GameState.LOGGED_IN && client.getLocalPlayer() != null
			&& world != null && !world.isInstance() && tracker.leaveRaid())
		{
			saveAndPublish();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (running)
		{
			publish();
		}
	}

	@Subscribe
	public void onVarClientStrChanged(VarClientStrChanged event)
	{
		if (running && event.getIndex() >= VarClientID.TFA_CLIENT_NAME0 && event.getIndex() <= VarClientID.TFA_CLIENT_NAME7)
		{
			// The game refreshes all eight slots in one script; wait for that refresh to finish.
			clientThread.invokeLater(() ->
			{
				if (running && captureParty())
				{
					saveAndPublish();
				}
			});
		}
	}

	private void reconcile(boolean announce)
	{
		if (configManager.getRSProfileKey() == null || client.getGameState() != GameState.LOGGED_IN || client.getMessages() == null)
		{
			return;
		}
		List<MessageNode> messages = new ArrayList<>();
		for (MessageNode node : client.getMessages())
		{
			if (node.getType() == ChatMessageType.GAMEMESSAGE && node.getTimestamp() * 1000L >= tracker.lastEvent)
			{
				messages.add(node);
			}
		}
		messages.sort(Comparator.comparingInt(MessageNode::getTimestamp).thenComparingInt(MessageNode::getId));
		boolean changed = false;
		for (MessageNode node : messages)
		{
			changed |= accept(node.getValue(), node.getTimestamp() * 1000L, announce);
		}
		if (changed)
		{
			captureParty();
			saveAndPublish();
		}
	}

	private boolean accept(String message, long timestamp, boolean announce)
	{
		TfaRaid before = tracker.raids.isEmpty() ? null : tracker.raids.get(0).copy();
		if (!tracker.accept(message, timestamp)) { return false; }
		TfaRaid latest = tracker.raids.isEmpty() ? null : tracker.raids.get(0);
		if (latest != null && (latest.active() || before == null || !before.id.equals(latest.id)))
		{
			awaitingRaidStart = false;
		}
		if (announce)
		{
			announce(before);
		}
		return true;
	}

	private void announce(TfaRaid before)
	{
		TfaRaid after = tracker.raids.isEmpty() ? null : tracker.raids.get(0);
		for (String text : TfaTiming.messages(before, after, config))
		{
			chatMessageManager.queue(QueuedMessage.builder().type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(text).build());
		}
	}

	TfaRaid displayRaid() { return displayRaid; }
	TfaLiveState liveState() { return liveState; }

	boolean timingVisible()
	{
		return running && client.getGameState() == GameState.LOGGED_IN && liveState.inRaid;
	}

	private boolean captureParty()
	{
		WorldView world = client.getTopLevelWorldView();
		if (tracker.current() == null || world == null || !world.isInstance() || !raidHudVisible())
		{
			return false;
		}
		List<String> names = new ArrayList<>();
		for (int slot = VarClientID.TFA_CLIENT_NAME0; slot <= VarClientID.TFA_CLIENT_NAME7; slot++)
		{
			names.add(client.getVarcStrValue(slot));
		}
		return tracker.party(names);
	}

	private boolean raidHudVisible()
	{
		Widget hud = client.getWidget(InterfaceID.TfaHud.UNIVERSE);
		return client.getGameState() == GameState.LOGGED_IN && hud != null && !hud.isHidden();
	}

	private void load()
	{
		ocellus = new TfaOcellus();
		tracker = new TfaTracker();
		storageHealthy = true;
		try
		{
			String json = configManager.getRSProfileConfiguration(GROUP, "history");
			if (json != null)
			{
				TfaTracker saved = gson.fromJson(json, TfaTracker.class);
				if (saved != null)
				{
					tracker = saved;
				}
			}
		}
		catch (RuntimeException ex)
		{
			storageHealthy = false;
			log.warn("Unable to read TFA splits history; preserving the stored data", ex);
		}
	}

	private void saveAndPublish()
	{
		if (storageHealthy && configManager.getRSProfileKey() != null)
		{
			configManager.setRSProfileConfiguration(GROUP, "history", gson.toJson(tracker));
		}
		publish();
	}

	private void delete(String raidId, String room)
	{
		String profile = configManager.getRSProfileKey();
		clientThread.invokeLater(() ->
		{
			if (running && profile != null && profile.equals(configManager.getRSProfileKey()) && tracker.delete(raidId, room))
			{
				saveAndPublish();
			}
		});
	}

	private void undoDelete()
	{
		String profile = configManager.getRSProfileKey();
		clientThread.invokeLater(() ->
		{
			if (running && profile != null && profile.equals(configManager.getRSProfileKey()) && tracker.undoDelete())
			{
				saveAndPublish();
			}
		});
	}

	private void publish()
	{
		// Swing receives its own immutable-in-practice copy; the game thread owns the reducer.
		TfaTracker snapshot = gson.fromJson(gson.toJson(tracker), TfaTracker.class);
		displayRaid = awaitingRaidStart || snapshot.raids.isEmpty() ? null : snapshot.raids.get(0);
		infoBoxManager.removeIf(box -> box instanceof TfaSplitInfoBox);
		if (displayRaid != null)
		{
			for (TfaRaid.Split split : displayRaid.splits)
			{
				if (split.duration >= 0) { infoBoxManager.addInfoBox(new TfaSplitInfoBox(this, config, split)); }
			}
		}
		TfaSplitsTrackerPanel target = panel;
		boolean healthy = storageHealthy;
		liveAvailable = raidHudVisible();
		TfaLiveState state = liveState;
		SwingUtilities.invokeLater(() ->
		{
			if (running && panel == target)
			{
				target.update(snapshot, healthy, state);
			}
		});
	}

	static BufferedImage icon()
	{
		BufferedImage image = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(99, 218, 204));
		g.setStroke(new BasicStroke(2));
		g.drawOval(4, 5, 16, 16);
		g.drawLine(12, 8, 12, 13);
		g.drawLine(12, 13, 16, 15);
		g.drawLine(9, 2, 15, 2);
		g.drawLine(12, 2, 12, 5);
		g.dispose();
		return image;
	}
}

package com.tfasplitstracker;

import java.util.ArrayList;
import java.util.List;

/** Room server times and observed phase times for the local chatbox. */
final class TfaTiming
{
	private TfaTiming() { }

	static String label(String room)
	{
		TfaRoom known = TfaRoom.find(room);
		return known == null ? room : known.label;
	}

	static List<String> messages(TfaRaid before, TfaRaid after, TfaSplitsTrackerConfig config)
	{
		List<String> messages = new ArrayList<>();
		if (after == null) { return messages; }
		boolean sameRaid = before != null && before.id.equals(after.id);
		if (config.chatOcellusPhases())
		{
			for (TfaRaid.Split split : after.splits)
			{
				for (TfaRaid.Phase phase : split.phases)
				{
					boolean recorded = sameRaid && before.splits.stream().filter(s -> s.room.equals(split.room))
						.flatMap(s -> s.phases.stream()).anyMatch(p -> p.number == phase.number && p.duration >= 0);
					if (phase.duration < 0 || recorded) { continue; }
					TfaRaid.Phase reference = config.chatPersonalBest() && after.personalBest != null
						? after.personalBest.phase(split, phase.number) : null;
					messages.add("TFA: Ocellus " + TfaOcellus.label(phase.number) + " - " + TfaRaid.time(phase.duration)
						+ (reference == null ? "" : " | vs scale " + after.personalBest.scale + " PB: "
							+ TfaPersonalBest.delta(phase.duration - reference.duration)));
				}
			}
		}
		if (config.chatSplits())
		{
			for (TfaRaid.Split split : after.splits)
			{
				boolean alreadyCompleted = sameRaid && before.splits.stream()
					.anyMatch(old -> old.room.equals(split.room) && old.duration >= 0);
				if (split.duration >= 0 && !alreadyCompleted)
				{
					String comparison = config.chatPersonalBest() && after.personalBest != null
						? after.personalBest.comparison(split) : "";
					messages.add("TFA: " + label(split.room) + " - " + TfaRaid.time(split.duration)
						+ " (raid split " + TfaRaid.time(split.cumulative) + ")"
						+ (comparison.isEmpty() ? "" : " | vs scale " + after.personalBest.scale + " PB: " + comparison));
				}
			}
		}
		if (config.chatTotal() && "Completed".equals(after.status)
			&& (!sameRaid || !"Completed".equals(before.status)))
		{
			messages.add("TFA: Raid complete - " + TfaRaid.time(after.total)
				+ (config.chatPersonalBest() && after.personalBest != null
					? " | vs scale " + after.personalBest.scale + " PB: " + TfaPersonalBest.delta(after.total - after.personalBest.total) : ""));
		}
		return messages;
	}
}

package com.tfasplitstracker;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Event reducer shared by live chat, chat-buffer recovery, and recorded-log tests. */
final class TfaTracker
{
	private static final String TIME = "(\\d+:\\d{2}(?::\\d{2})?(?:\\.\\d{1,3})?)";
	private static final Pattern START = Pattern.compile("^Challenge started: (.+)\\.$");
	private static final Pattern SPLIT = Pattern.compile("^Challenge complete: (.+)\\. Duration: " + TIME + "\\. Total: " + TIME + ".*$");
	private static final Pattern TOTAL = Pattern.compile("^The Fractured Archive: Total completion time: " + TIME + ".*$");
	private static final Pattern READY = Pattern.compile("^\\d+/([1-8]) party members are now ready\\.$");
	final List<TfaRaid> raids = new ArrayList<>();
	// Persist the event journal as well as the records, so re-enabling cannot replay old starts.
	final Set<String> processed = new LinkedHashSet<>();
	long lastEvent;
	TfaRaid deleted;
	int deletedIndex;
	boolean suppressUntilNextRaid;

	boolean delete(String raidId, String room)
	{
		for (int i = 0; i < raids.size(); i++)
		{
			TfaRaid raid = raids.get(i);
			if (!raid.id.equals(raidId) || room != null && raid.active())
			{
				continue;
			}
			if (room != null && raid.splits.stream().noneMatch(s -> s.room.equals(room)))
			{
				return false;
			}
			if (raid.active())
			{
				suppressUntilNextRaid = true;
			}
			else
			{
				deleted = raid.copy();
				deletedIndex = i;
			}
			if (room == null)
			{
				raids.remove(i);
			}
			else
			{
				raid.splits.removeIf(s -> s.room.equals(room));
			}
			// Keep the event journal: retained chat must not resurrect a deleted record.
			return true;
		}
		return false;
	}

	boolean undoDelete()
	{
		if (deleted == null)
		{
			return false;
		}
		raids.removeIf(r -> r.id.equals(deleted.id));
		// A newly started raid must remain first so current() can find it.
		int firstSaved = current() == null ? 0 : 1;
		raids.add(Math.min(raids.size(), Math.max(firstSaved, deletedIndex)), deleted);
		deleted = null;
		while (raids.size() > 200)
		{
			raids.remove(raids.size() - 1);
		}
		return true;
	}

	TfaRaid current()
	{
		return !raids.isEmpty() && raids.get(0).active() ? raids.get(0) : null;
	}

	boolean leaveRaid()
	{
		TfaRaid raid = current();
		if (raid == null) { return false; }
		// Preserve server timings and the event journal; leaving is not a completed split.
		raid.status = "Left raid";
		return true;
	}

	boolean accept(String raw, long timestamp)
	{
		if (raw == null)
		{
			return false;
		}
		String message = raw.replaceAll("<[^>]*>", "").replace('\u00a0', ' ').trim();
		Matcher start = START.matcher(message);
		Matcher split = SPLIT.matcher(message);
		Matcher total = TOTAL.matcher(message);
		Matcher ready = READY.matcher(message);
		TfaRoom startRoom = start.matches() ? TfaRoom.find(start.group(1)) : null;
		TfaRoom completedRoom = split.matches() ? TfaRoom.find(split.group(1)) : null;
		boolean isStart = startRoom != null;
		boolean isSplit = completedRoom != null;
		boolean isTotal = total.matches();
		boolean isReady = ready.matches() && current() != null;
		boolean failed = message.equals("You failed to survive the Fractured Archive.");
		boolean abandoned = message.equals("You abandon the raid and leave the Fractured Archive.");
		if (!isStart && !isSplit && !isTotal && !isReady && !failed && !abandoned)
		{
			return false;
		}
		String key = timestamp + ":" + message;
		if (processed.contains(key) || timestamp < lastEvent)
		{
			return false;
		}
		processed.add(key);
		while (processed.size() > 4096)
		{
			processed.remove(processed.iterator().next());
		}
		lastEvent = timestamp;
		if (suppressUntilNextRaid)
		{
			if (isStart && startRoom == TfaRoom.GUARDIAN)
			{
				suppressUntilNextRaid = false;
			}
			else
			{
				return true;
			}
		}
		if (isStart)
		{
			String room = startRoom.key;
			TfaRaid raid = current();
			TfaRaid.Split previous = raid == null || raid.splits.isEmpty() ? null : raid.splits.get(raid.splits.size() - 1);
			if (previous != null && room.equals(previous.room) && previous.duration < 0 && previous.started == timestamp)
			{
				return true;
			}
			if (raid != null && room.equals("Archive Guardian"))
			{
				raid.status = "Interrupted";
				raid = null;
			}
			if (raid == null)
			{
				raid = create(timestamp);
			}
			TfaRaid.Split next = new TfaRaid.Split();
			next.room = room;
			next.started = timestamp;
			raid.splits.add(next);
			raid.updated = timestamp;
		}
		else if (isSplit)
		{
			String room = completedRoom.key;
			long duration = parseTime(split.group(2));
			long cumulative = parseTime(split.group(3));
			TfaRaid raid = current();
			if (raid != null && room.equals("Archive Guardian")
				&& raid.splits.stream().anyMatch(s -> s.room.equals(room) && s.duration >= 0))
			{
				// The next run's first completion also recovers a missed first-room start.
				raid.status = "Interrupted";
				raid = null;
			}
			if (raid == null)
			{
				// Ocellus and the overall message are separate signals for the same finish.
				TfaRaid last = raids.isEmpty() ? null : raids.get(0);
				if (last != null && "Completed".equals(last.status) && Math.abs(timestamp - last.updated) <= 2000)
				{
					raid = last;
				}
				else
				{
					raid = create(timestamp - cumulative);
				}
			}
			TfaRaid.Split result = raid.splits.stream().filter(s -> s.room.equals(room)).findFirst().orElse(null);
			if (result == null)
			{
				result = new TfaRaid.Split();
				result.room = room;
				result.started = timestamp - duration;
				raid.splits.add(result);
			}
			result.duration = duration;
			result.cumulative = cumulative;
			raid.total = cumulative;
			raid.updated = timestamp;
			if (room.equals("Ocellus"))
			{
				TfaOcellus.finish(result);
				raid.status = "Completed";
			}
		}
		else if (isTotal)
		{
			TfaRaid raid = current();
			if (raid == null && !raids.isEmpty() && "Completed".equals(raids.get(0).status)
				&& Math.abs(timestamp - raids.get(0).updated) <= 2000)
			{
				raid = raids.get(0);
			}
			long duration = parseTime(total.group(1));
			if (raid == null)
			{
				raid = create(timestamp - duration);
			}
			raid.total = duration;
			raid.updated = timestamp;
			raid.status = "Completed";
		}
		else if (current() != null)
		{
			TfaRaid raid = current();
			if (isReady)
			{
				raid.teamSize = Integer.parseInt(ready.group(1));
			}
			else
			{
				raid.status = failed ? "Failed" : "Abandoned";
				raid.updated = timestamp;
			}
		}
		if (!raids.isEmpty()) { TfaPersonalBest.select(raids.get(0), raids); }
		return true;
	}

	private TfaRaid create(long timestamp)
	{
		TfaRaid raid = new TfaRaid();
		raid.started = timestamp;
		raid.updated = timestamp;
		raids.add(0, raid);
		while (raids.size() > 200)
		{
			raids.remove(raids.size() - 1);
		}
		return raid;
	}

	boolean party(List<String> names)
	{
		TfaRaid raid = current();
		if (raid == null || names.isEmpty())
		{
			return false;
		}
		boolean changed = false;
		Set<String> visible = new java.util.TreeSet<>(String.CASE_INSENSITIVE_ORDER);
		for (String raw : names)
		{
			String name = raw == null ? "" : raw.replaceAll("<[^>]*>", "").replace('\u00a0', ' ').trim();
			if (!name.isEmpty()) { visible.add(name); }
			if (!name.isEmpty() && raid.members.stream().noneMatch(n -> n.equalsIgnoreCase(name)))
			{
				raid.members.add(name);
				changed = true;
			}
		}
		// A partial refresh or a departing member must not shrink the raid's scale.
		if (visible.size() > raid.observedTeamSize)
		{
			raid.observedTeamSize = visible.size();
			TfaPersonalBest.select(raid, raids);
			changed = true;
		}
		return changed;
	}

	static long parseTime(String value)
	{
		String[] parts = value.split(":");
		long seconds = 0;
		for (int i = 0; i < parts.length - 1; i++)
		{
			seconds = (seconds + Long.parseLong(parts[i])) * 60;
		}
		return seconds * 1000 + new java.math.BigDecimal(parts[parts.length - 1]).movePointRight(3).longValueExact();
	}
}

